output_text:
[
  {
    "id": "must_take_store_cart",
    "text": "The shopper is obliged to take the store cart from the cart bay before completing the trip.",
    "abstraction": {
      "state_properties": {
        "cart_bay": "at(1,5)"
      },
      "events": {
        "pickup_cart_at_bay": {
          "pre": {
            "and": [
              "cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_cart_at_bay"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "The shopper is prohibited from carrying items by hand rather than using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "The shopper may pick up shelf items only while in possession of the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "return_cart_after_shopping",
    "text": "After putting any item into the cart, the shopper is obliged to return the cart to the front-left return bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "cart_parked_at_return": "cartAt(0,1)"
      },
      "events": {
        "loaded_item_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": null
        },
        "leave_cart_at_return": {
          "pre": {
            "and": [
              "return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "loaded_item_into_cart",
      "discharge": "leave_cart_at_return"
    }
  },
  {
    "id": "park_only_at_return_bay",
    "text": "The shopper is prohibited from leaving the cart anywhere except the designated return bay.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "outside_return_bay": {
          "not": "return_bay"
        }
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "exit_without_cart",
    "text": "The shopper is prohibited from exiting the store while still holding or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "at_exit",
              "hasCart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_carts_in_exit_zone",
    "text": "Carts are prohibited in the customer-only exit approach zone on the right side of the store.",
    "abstraction": {
      "state_properties": {
        "customer_only_exit_zone": {
          "or": [
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(7,5)",
            "at(8,1)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "cart_in_exit_zone": {
          "and": [
            "hasCart",
            "customer_only_exit_zone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_zone"
    }
  },
  {
    "id": "exit_requires_cart_returned",
    "text": "The shopper may exit only after the cart has been parked at the designated return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cart_parked_at_return"
        }
      },
      "events": {
        "exit_before_cart_returned": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_returned"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_before_cart_returned"
    }
  }
]
